    for (int i = 0; i < M; ++i) {
        cin >> second[i];
    }

    int max_length = 0;

    // Try all possible lengths of the subsequence
    for (int length = 1; length <= min(N, M); ++length) {
        vector<pair<long long, long long>> hashes_first;
        for (int i = 0; i <= N - length; ++i) {
            hashes_first.push_back(hash_value(first, i, i + length - 1));
        }

        vector<pair<long long, long long>> hashes_second;
        for (int i = 0; i <= M - length; ++i) {
            hashes_second.push_back(hash_value(second, i, i + length - 1));
        }

        // Check if any hash in hashes_first matches any hash in hashes_second
        for (auto& h1 : hashes_first) {
            for (auto& h2 : hashes_second) {
                if (h1 == h2) {
                    // Verify the actual subsequence
                    for (int i = 0; i < N - length + 1; ++i) {
                        if (verify_subsequence(first, i, i + length - 1, second, 0, length - 1)) {
                            max_length = length;
                            goto next_length;
                        }
                    }
                }
            }
        }

        next_length:;
    }

    cout << max_length << endl;
    return 0;
}
```

