```cpp
// UI.cpp
#include "UI.h"
#include <iostream>

UI::UI(Game& game) : game(game), window(sf::VideoMode(800, 600), "Chess"), font(), text() {
    if (!font.loadFromFile("arial.ttf")) {
        std::cerr << "Could not load font\n";
    }
    text.setFont(font);
    text.setCharacterSize(24);
    text.setFillColor(sf::Color::White);
    game.attach(this); // Register UI as an observer
}

void UI::run() {
    while (window.isOpen()) {
        handleEvents();
        window.clear();
        drawBoard();
        drawButtons();
        window.display();
    }
}

void UI::drawBoard() {
    for (int i = 0; i < 8; ++i) {
        for (int j = 0; j < 8; ++j) {
            sf::RectangleShape square(sf::Vector2f(100, 100));
            square.setPosition(i * 100, j * 100);
            square.setFillColor((i + j) % 2 == 0 ? sf::Color::White : sf::Color::Black);
            window.draw(square);
        }
    }
}

void UI::drawButtons() {
    sf::RectangleShape button(sf::Vector2f(200, 50));
    button.setFillColor(sf::Color::Blue);
    button.setPosition(300, 550);

    sf::Text buttonText("Player Rating", font, 24);
    buttonText.setFillColor(sf::Color::White);
    buttonText.setPosition(310, 560);

    window.draw(button);
    window.draw(buttonText);
}

void UI::handleEvents() {
    sf::Event event;
    while (window.pollEvent(event)) {
        if (event.type == sf::Event::Closed) {
            window.close();
        }
        if (event.type == sf::Event::MouseButtonPressed) {
            if (event.mouseButton.button == sf::Mouse::Left) {
                int x = event.mouseButton.x;
                int y = event.mouseButton.y;
                if (x >= 300 && x <= 500 && y >= 550 && y <= 600) {
                    showRating();
                }
            }
        }
    }
}

void UI::displaySettings() {
    // Display settings panel
}

void UI::displayRating() {
