    sf::Text ratingText("", font, 24);
    ratingText.setFillColor(sf::Color::White);
    ratingText.setPosition(10, 10);

    std::ifstream file("rating.txt");
    std::string line;
    ratingText.setString("");
    while (std::getline(file, line)) {
        ratingText.setString(ratingText.getString() + line + "\n");
    }

    while (ratingWindow.isOpen()) {
        sf::Event event;
        while (ratingWindow.pollEvent(event)) {
            if (event.type == sf::Event::Closed) {
                ratingWindow.close();
            }
        }
        ratingWindow.clear();
        ratingWindow.draw(ratingText);
        ratingWindow.display();
    }
}

void UI::update() {
