// Function to simulate the network in parallel
void simulate_network_parallel(std::vector<Neuron>& neurons, double dt, int num_steps, int num_threads) {
    std::vector<std::thread> threads(num_threads);

    for (int step = 0; step < num_steps; ++step) {
        double t = step * dt;

        // Reset external input for all neurons
        auto start_reset = std::chrono::high_resolution_clock::now();
        for (auto& neuron : neurons) {
            neuron.reset_input();
        }
        auto end_reset = std::chrono::high_resolution_clock::now();
        std::chrono::duration<double> reset_duration = end_reset - start_reset;
        std::cout << "Reset time: " << reset_duration.count() << " seconds" << std::endl;

        // Propagate spikes from neurons to their connected neighbors
        auto start_propagate = std::chrono::high_resolution_clock::now();
        for (auto& neuron : neurons) {
            if (neuron.has_spiked()) {
                for (const auto& [target_id, weight] : neuron.outputs) {
                    neurons[target_id].receive_input(weight);
                }
            }
        }
        auto end_propagate = std::chrono::high_resolution_clock::now();
        std::chrono::duration<double> propagate_duration = end_propagate - start_propagate;
        std::cout << "Propagate time: " << propagate_duration.count() << " seconds" << std::endl;

        // Update the state of each neuron in parallel
        auto start_update = std::chrono::high_resolution_clock::now();
        for (int i = 0; i < num_threads; ++i) {
            threads[i] = std::thread([&, i, num_threads, t, dt]() {
                size_t start = i * neurons.size() / num_threads;
                size_t end = (i + 1) * neurons.size() / num_threads;
                for (size_t j = start; j < end; ++j) {
                    neurons[j].update(dt, neurons[j].external_input, t);
                }
            });
        }
        for (auto& thread : threads) {
            thread.join();
        }
        auto end_update = std::chrono::high_resolution_clock::now();
        std::chrono::duration<double> update_duration = end_update - start_update;
        std::cout << "Update time: " << update_duration.count() << " seconds" << std::endl;

        // Print the state of the neurons (for debugging)
        for (size_t i = 0; i < neurons.size(); ++i) {
            std::cout << "Neuron " << i << ": v = " << neurons[i].get_v() << ", spike = " << neurons[i].has_spiked() << std::endl;
        }
    }
}

// Function to measure memory usage
void measure_memory_usage() {
    struct rusage rusage;
    getrusage(RUSAGE_SELF, &rusage);
    long memory_usage_kb = rusage.ru_maxrss;
    std::cout << "Memory usage: " << memory_usage_kb << " KB" << std::endl;
}

